import os,json,urllib.request
from pathlib import Path

class C:
    def __init__(self,u=None,k=None):
        self.u=u or os.environ.get('LLM_URL','http://localhost:8080/v1/chat/completions')
        self.k=k or os.environ.get('LLM_KEY','')
        self.t=int(os.environ.get('LLM_TIMEOUT','30'))

    def q(self,p,m='gpt-4',temp=.7,max_t=4096):
        d={'model':m,'messages':[{'role':'user','content':p}],'temperature':temp,'max_tokens':max_t}
        b=json.dumps(d).encode()
        h={'Content-Type':'application/json'}
        if self.k:h['Authorization']=f'Bearer {self.k}'
        req=urllib.request.Request(self.u,data=b,headers=h,method='POST')
        try:
            with urllib.request.urlopen(req,timeout=self.t) as r:
                return json.loads(r.read().decode())
        except Exception as e:
            return{'e':str(e)}

    def complete(self,p,m=None):
        r=self.q(p,m or os.environ.get('LLM_MODEL','gpt-4'))
        return r.get('choices',[{}])[0].get('message',{}).get('content','') if 'choices' in r else str(r.get('e',''))

if __name__=='__main__':
    import sys
    c=C()
    print(c.complete(sys.argv[1] if len(sys.argv)>1 else 'hello'))

import os,json,subprocess,time
from pathlib import Path

def R(c,t=3):
    try:
        p=subprocess.run(c,shell=True,capture_output=True,text=True,timeout=t)
        return{'o':p.stdout,'e':p.stderr,'r':p.returncode}
    except Exception as e:
        return{'o':'','e':str(e),'r':-1}

def health(url='http://localhost:8888/health',t=2):
    return R(f'curl -s -m {t} {url}',t+1)

def detect_env():
    r=[]
    if Path('/proc/self/cgroup').exists():
        with open('/proc/self/cgroup') as f:
            if 'kubepods' in f.read():r.append('k8s')
    if Path('/run/service').exists():r.append('s6')
    if Path('/.dockerenv').exists():r.append('docker')
    return r

def restart_kernel(path='/app/kernel_server.py',port=8888,t=30):
    env=os.environ.copy()
    env['PYTHONUNBUFFERED']='1'
    log=Path('/tmp/kernel_restart.log')
    with open(log,'w') as f:
        p=subprocess.Popen(['python3',path,'--host','0.0.0.0','--port',str(port),'--log-level','info'],
            cwd='/mnt/agents',env=env,stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
    for i in range(t):
        h=health()
        if 'kernel_alive' in h.get('o',''):
            return{'ok':True,'pid':p.pid}
        time.sleep(1)
    return{'ok':False,'pid':p.pid}

if __name__=='__main__':
    print(json.dumps({'env':detect_env(),'health':health()},indent=2))

